    public LegalHold addToRepositories( UUID parentId, RecordsRepository addTo ) {
	    LOGGER.info("handling AssignRepositoriesToLegalHoldEvent - " );
	    
	    LegalHold parentEntity = repository.findById(parentId).get();
	    RecordsRepository child = registry.project( RecordsRepository.class, addTo.getRecordsRepositoryId());
	    
	    parentEntity.getRepositories().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

