	    LegalHold parentEntity = repository.findById(parentId).get();
	    RecordsRepository child = registry.project( RecordsRepository.class, removeFrom.getRecordsRepositoryId());
	    
	    parentEntity.getRepositories().remove( child );
	
	    // ------------------------------------------
		// save
